class Solution {
public:
    string shiftingLetters(string s, vector<vector<int>>& shifts) {
        int n = (int)s.size();
        vector<int> diff(n + 1, 0);
        for (auto& sh : shifts) {
            int l = sh[0], r = sh[1], d = sh[2];
            int v = (d == 1) ? 1 : -1;
            diff[l] += v;
            diff[r + 1] -= v;
        }
        int cur = 0;
        for (int i = 0; i < n; i++) {
            cur += diff[i];
            int shift = ((cur % 26) + 26) % 26;
            s[i] = (char)('a' + (s[i] - 'a' + shift) % 26);
        }
        return s;
    }
};
